/**
 * A plan as a card: name, tagline, price per month, the features, a call to action and an optional slot for more
 * actions. Text comes in through `labels`; the plan is data.
 */
import { For, type JSX } from "solid-js";
import { Badge } from "../primitives/badge/badge";
import { Block } from "../primitives/block/block";
import { Box } from "../primitives/box/box";
import { Button } from "../primitives/button/button";
import { CardContent } from "../primitives/card/card-content";
import { CardDescription } from "../primitives/card/card-description";
import { CardFooter } from "../primitives/card/card-footer";
import { CardHeader } from "../primitives/card/card-header";
import { CardTitle } from "../primitives/card/card-title";
import { Group } from "../primitives/group/group";
import { List } from "../primitives/list/list";
import { ListItem } from "../primitives/list/list-item";
import { Text } from "../primitives/text/text";
import { Title } from "../primitives/title/title";
import { cn, fmtMoney, tpl } from "../utils";
import type { Plan, PricingCardLabels } from "./pricing-card.types";

export type PricingCardProps = {
  plan: Plan;
  labels: PricingCardLabels;
  current?: boolean;
  emphasis?: "auto" | "off";
  density?: "default" | "compact";
  billing?: "monthly" | "annual";
  footer?: (plan: Plan) => JSX.Element;
  onSelect?: (id: string) => void;
};

export function PricingCard({
  plan,
  labels,
  current,
  emphasis = "auto",
  density = "default",
  billing = "monthly",
  footer,
  onSelect,
}: PricingCardProps) {
  const stand = plan.highlighted && ((emphasis as string) === "auto");
  const yearlyOn = ((billing as string) === "annual") && (plan.yearly > 0);
  const amount = yearlyOn ? plan.yearly : plan.price;
  return (
    <Block
      tag="article"
      class={cn(
        "flex flex-col gap-8 bg-card p-6 text-card-foreground inset-ring inset-ring-border rounded",
        "flex h-full flex-col"
      )}
      data-slot="card"
      data-highlighted={(stand ? "true" : "false")}
      data-current={(current ? "true" : "false")}
    >
      <CardHeader class="flex flex-col gap-2">
        <Box class="flex min-h-6 items-center" data-slot="badge-slot">
          {stand ? (
            <Badge variant="default" size="default">
              {labels.popular}
            </Badge>
          ) : null}
        </Box>
        <CardTitle as={3}>
          {plan.name}
        </CardTitle>
        <CardDescription>
          {plan.tagline}
        </CardDescription>
      </CardHeader>
      <CardContent class={cn("flex flex-1 flex-col", (((density as string) === "compact") ? "gap-2" : "gap-4"))}>
        <Group gap="2" align="baseline">
          <Title as={2} size="4xl" weight="bold">
            {(amount === 0) ? (
              <>
                {labels.free}
              </>
            ) : (
              <>
                {fmtMoney(amount, plan.currency)}
              </>
            )}
          </Title>
          {(amount > 0) ? (
            <Text size="sm" class="text-muted-foreground">
              {(yearlyOn ? labels.perYear : labels.perMonth)}
            </Text>
          ) : null}
        </Group>
        <Text size="sm" weight="medium">
          {tpl(labels.seats, plan.seats)}
        </Text>
        <Text size="sm" class="text-muted-foreground">
          {tpl(labels.storage, plan.storage)}
        </Text>
        <List tag="ul" class="flex flex-col gap-2 text-sm">
          <For each={plan.features ?? []}>{(feature) => (
            <ListItem class="flex gap-2">
              {feature}
            </ListItem>
          )}</For>
        </List>
      </CardContent>
      <CardFooter class="flex flex-wrap items-center gap-2">
        <Button
          variant={(stand ? "default" : "outline")}
          size="default"
          data-testid="plan-select"
          onClick={() => onSelect?.(plan.id)}
        >
          {labels.cta}
        </Button>
        {footer?.(plan)}
      </CardFooter>
    </Block>
  );
}

// Code generated by xgen. DO NOT EDIT.
// Source: xgen/screens/src/authoring/blocks/pricing-card.ts

export type Plan = {
  id: string;
  name: string;
  tagline: string;
  price: number;
  currency: string;
  seats: number;
  storage: number;
  highlighted: boolean;
  status: string;
  features: string[];
  yearly: number;
};

export type PricingCardLabels = {
  popular: string;
  perMonth: string;
  seats: string;
  storage: string;
  cta: string;
  free: string;
  perYear: string;
};
